#!/bin/sh
# Own run status/evidence postprocessing only. No SUT call or new grant.
set -eu
umask 077
base=/root/t44-r9/independent772
unit=t44-r29-independent772-01
mkdir -p "$base/public" "$base/retained/r29qa772-01"
base64 -d > "$base/public/QA772_READONLY_COLLECT.py" <<'PUBLIC_READONLY_COLLECTOR'

PUBLIC_READONLY_COLLECTOR
chmod 700 "$base/public/QA772_READONLY_COLLECT.py"
systemctl show "$unit" --property=Id,LoadState,ActiveState,SubState,Result,ExecMainStatus,MainPID,ExecMainStartTimestamp,ExecMainExitTimestamp,RuntimeMaxUSec --no-pager > "$base/public/qa772-unit.properties"
# Preserve full own-unit failure evidence privately; never print raw journal/source.
journalctl -u "$unit" --no-pager -o short-iso > "$base/retained/r29qa772-01/unit-log.latest.private.log"
if [ ! -f "$base/retained/r29qa772-01/unit-log.first.private.log" ]; then
  cp "$base/retained/r29qa772-01/unit-log.latest.private.log" "$base/retained/r29qa772-01/unit-log.first.private.log"
fi
docker run --rm --pull=never --network none --cpus 2 --memory 8g --pids-limit 64 \
  --read-only --cap-drop ALL --security-opt no-new-privileges \
  --tmpfs /tmp:rw,nosuid,nodev,size=64m \
  --mount "type=bind,src=$base,dst=/private" --entrypoint python3 \
  sha256:4f3baf081863a4580b5608699d9a7a8af2d89c3e87abbb60089b630b9102b2a1 \
  /private/public/QA772_READONLY_COLLECT.py
